import * as U from '../ui.js';
U.mount(()=>U.heading('Your academic home base','My courses.','Everything you need for each subject, together.','<div class="import-toolbar-actions"><a class="btn" href="import.html">Import file</a>'+U.button('Add course','courses')+'</div>')+`<div class="grid2">${U.db.courses.map(c=>{let a=U.attendanceStats(c.id),n=U.db.tasks.filter(t=>t.course_id===c.id&&!['done','cancelled'].includes(t.status)).length;return `<article class="card course-card subject-colored" style="${U.subjectStyle(c.id)}"><div class="section-head"><div class="course-symbol">${U.icon('book')}</div>${U.edit('courses',c.id)}</div>${U.tag(c.course_code,'blue')}<h2><a href="course.html?id=${c.id}">${U.esc(c.name)}</a></h2><p class="muted">${U.esc(c.professor_name||'Professor not set')}<br>${U.esc(c.semester)}</p><footer><span class="small muted">${n} open tasks · ${a.percent===null?'No':a.percent+'%'} attendance</span><a class="text-link" href="course.html?id=${c.id}">Open course →</a></footer></article>`}).join('')||U.empty('Add your first course to get started.')}</div>`);
